-- Source-backed Italian spell descriptions from immutable priority snapshot ranks 401-600.
-- Source English, placeholders, and line breaks are preserved.
-- Excluded internal/test entries: 20240, 21392, 21896, 22047, 23789.
local _, ns = ...
ns.data = ns.data or {}
ns.data.spellDescriptionOverrides = ns.data.spellDescriptionOverrides or {}
local verifiedSpellDescriptions = {
    [19552] = { en = "While Aspect of the Hawk is active, Auto Shot has a $s1% chance of increasing ranged attack speed by $6150s1% for $6150d. While Aspect of the Beast is active, all melee auto attacks have a $s2% chance of increasing melee attack speed by $1299448s1% for $1299448d.", description = "Quando l'Aspetto del Falco è attivo, Tiro Automatico ha una probabilità del $s1% di aumentare la velocità d'attacco a distanza del $6150s1% per $6150d. Quando è attivo l'Aspetto della Bestia, tutti gli attacchi automatici in mischia hanno una probabilità del $s2% di aumentare la velocità d'attacco in mischia del $1299448s1% per $1299448d." },
    [19559] = { en = "Increases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by $s1%.", description = "Aumenta del $s1% il bonus alla velocità dei tuoi Aspetti del Ghepardo e del Branco." },
    [19572] = { en = "Gives your Mend Pet spell a $s1% chance of cleansing $24406s1 Curse, Disease, Magic, or Poison effect from your pet each time it heals and reduces the Mana cost by $s2%.", description = "Dà all'incantesimo Cura Famiglio una probabilità del $s1% di rimuovere dal tuo famiglio un effetto di Maledizione, Malattia, Magia o Veleno ($24406s1) ogni volta che lo cura e riduce il costo in mana del $s2%." },
    [19577] = { en = "Command your pet to Stun the target for $24394d on its next successful attack, which also gains $m2% increased critical strike chance. Generates high threat.", description = "Ordina al tuo famiglio di stordire il bersaglio per $24394d al prossimo attacco riuscito; l'attacco ottiene anche un aumento del $m2% alla probabilità di critico. Genera molta minaccia." },
    [19578] = { en = "While your pet is active, you and your pet will regenerate $m1% of total health every $m2 sec.", description = "Finché il tuo famiglio è attivo, tu e lui rigenerate il $m1% della salute totale ogni $m2 sec." },
    [19583] = { en = "Increases the Health and Armor of your pets by $s1%.", description = "Aumenta la salute e l'armatura dei tuoi famigli del $s1%." },
    [19596] = { en = "Increases the movement speed of your pets by $s1%.", description = "Aumenta la velocità di movimento dei tuoi famigli del $s1%." },
    [19598] = { en = "Increases the critical strike chance of your pets and hawks by $s1%.", description = "Aumenta la probabilità di critico dei tuoi famigli e falchi del $s1%." },
    [19609] = { en = "Increases the Armor of your pets by $s1%.", description = "Aumenta l'armatura dei tuoi famigli del $s1%." },
    [19616] = { en = "Increases the damage done by your pets and hawks by $s1%.", description = "Aumenta i danni inflitti dai tuoi famigli e falchi del $s1%." },
    [19621] = { en = "Gives your pet a $s1% chance to gain a $19615s1% attack speed increase for $19615d after dealing a critical strike.", description = "Dà al tuo famiglio una probabilità del $s1% di ottenere un aumento del $19615s1% alla velocità d'attacco per $19615d dopo aver inflitto un colpo critico." },
    [19655] = { en = "Taints the Felhunter's blood for $d.  When the Felhunter is hit with a melee attack, the attacker will lose $19652s1 melee attack power for $19652d.  Stacks up to 5 times on a single target.", description = "Contamina il sangue del Vilsegugio per $d. Quando il Vilsegugio viene colpito da un attacco in mischia, l'attaccante perde $19652s1 potenza d'attacco in mischia per $19652d. Si accumula fino a 5 volte sullo stesso bersaglio." },
    [19656] = { en = "Taints the Felhunter's blood for $d.  When the Felhunter is hit with a melee attack, the attacker will lose $19653s1 melee attack power for $19653d.  Stacks up to 5 times on a single target.", description = "Contamina il sangue del Vilsegugio per $d. Quando il Vilsegugio viene colpito da un attacco in mischia, l'attaccante perde $19653s1 potenza d'attacco in mischia per $19653d. Si accumula fino a 5 volte sullo stesso bersaglio." },
    [19660] = { en = "Taints the Felhunter's blood for $d.  When the Felhunter is hit with a melee attack, the attacker will lose $19654s1 melee attack power for $19654d.  Stacks up to 5 times on a single target.", description = "Contamina il sangue del Vilsegugio per $d. Quando il Vilsegugio viene colpito da un attacco in mischia, l'attaccante perde $19654s1 potenza d'attacco in mischia per $19654d. Si accumula fino a 5 volte sullo stesso bersaglio." },
    [19708] = { en = "If you spend at least 10 seconds eating you will become well fed and gain $s1 Stamina and Spirit for $d.", description = "Se mangi per almeno 10 secondi, sarai ben nutrito e otterrai $s1 Tempra e Spirito per $d." },
    [19731] = { en = "Purges $s1 harmful magic $leffect:effects; from a friend or $s1 beneficial magic $leffect:effects; from an enemy.  If an effect is devoured, the Felhunter will be healed for $19732s1.", description = "Rimuove $s1 $leffect:effects; di magia dannoso da un alleato o $s1 $leffect:effects; di magia benefico da un nemico. Se viene divorato un effetto, il Vilsegugio recupera $19732s1 salute." },
    [19734] = { en = "Purges $s1 harmful magic $leffect:effects; from a friend or $s1 beneficial magic $leffect:effects; from an enemy.  If an effect is devoured, the Felhunter will be healed for $19733s1.", description = "Rimuove $s1 $leffect:effects; di magia dannoso da un alleato o $s1 $leffect:effects; di magia benefico da un nemico. Se viene divorato un effetto, il Vilsegugio recupera $19733s1 salute." },
    [19746] = { en = "Gives a $s1% chance of ignoring spell interruption when damaged to all party members within $a1 yards.  Players may only have one Aura on them per Paladin at any one time.", description = "Dà a tutti i membri del gruppo una probabilità del $s1% di evitare l'interruzione degli incantesimi quando subiscono danni entro $a1 metri. Ogni paladino può applicare una sola Aura a ciascun giocatore." },
    [19748] = { en = "Decreases range at which monsters will attack party members within $a1 yards.  Players may only have one Aura on them per Paladin at any one time.", description = "Riduce il raggio entro il quale i mostri attaccano i membri del gruppo entro $a1 metri. Ogni paladino può applicare una sola Aura a ciascun giocatore." },
    [19752] = { en = "The paladin sacrifices $ghimself:herself; to remove the targeted party member from harms way.  Enemies will stop attacking the protected party member, who will be immune to all harmful attacks but cannot take any action for $19753d.", description = "Il paladino sacrifica $ghimself:herself; per sottrarre il membro del gruppo bersaglio al pericolo. I nemici smettono di attaccare il membro protetto, che diventa immune a tutti gli attacchi dannosi ma non può agire per $19753d." },
    [19755] = { en = "Increase the duration of Fear effects applied to the target by $s1% for $d.", description = "Aumenta del $s1% la durata degli effetti di Paura applicati al bersaglio per $d." },
    [19784] = { en = "Inflicts $s1 Fire damage and stuns targets in a $a1 yard radius for $d. Any damage will break the effect.", description = "Infligge $s1 danni da Fuoco e stordisce i bersagli entro un raggio di $a1 metri per $d. Qualsiasi danno interrompe l'effetto." },
    [19798] = { en = "Inflicts $s2 damage to nearby enemies.", description = "Infligge $s2 danni ai nemici vicini." },
    [19821] = { en = "Burns $s1 mana from those in the blast radius and does 50% of the mana drained in damage to the target. Also Silences targets in the blast for $d.", description = "Brucia $s1 mana a chi si trova nell'area dell'esplosione e infligge al bersaglio danni pari al 50% del mana prosciugato. Inoltre silenzia per $d i bersagli nell'area." },
    [19932] = { en = "Permanently enchant a cloak to give $13652s1 Fire Resistance.", description = "Incanta permanentemente un mantello conferendogli $13652s1 Resistenza al Fuoco." },
    [20022] = { en = "Creates a Soulstone that is automatically used upon death, restoring its owner to life at $3026s1% health and mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra dell'Anima che viene usata automaticamente alla morte per riportare in vita il proprietario con il $3026s1% di salute e mana.\r\n\r\nGli oggetti evocati scompaiono se si resta disconnessi per più di 15 minuti." },
    [20049] = { en = "Increases your Physical and Holy damage dealt by $s1% for $20050d after landing a non-periodic critical strike.  Stacks up to $20050u times.", description = "Aumenta del $s1% i danni fisici e sacri inflitti per $20050d dopo aver messo a segno un colpo critico non periodico. Si accumula fino a $20050u volte." },
    [20066] = { en = "Puts the enemy target in a state of meditation, incapacitating them for up to $d. Any damage caused will awaken the target. Only works against Humanoids.", description = "Induce il bersaglio nemico in uno stato di meditazione, incapacitandolo per un massimo di $d. Qualsiasi danno lo risveglia. Funziona solo sugli umanoidi." },
    [20101] = { en = "Reduces the Mana cost of all instant cast spells and abilities by $m1%.", description = "Riduce del $m1% il costo in mana di tutti gli incantesimi e le abilità a lancio istantaneo." },
    [20116] = { en = "Consecrates the land beneath the Paladin, doing ${$1280346m1*8} Holy damage over $d to enemies who enter the area The first $s3 enemies who enter the area will take an additional ${$1280346m2*8} damage over $d.", description = "Consacra il terreno sotto il paladino, infliggendo ${$1280346m1*8} danni sacri in $d ai nemici che entrano nell'area. I primi $s3 nemici che vi entrano subiscono inoltre ${$1280346m2*8} danni aggiuntivi in $d." },
    [20127] = { en = "Damaging melee attacks against you have a $h% chance to increase your chance to block by $m1%.  Lasts $20128d or $20128n blocks.", description = "Gli attacchi in mischia che ti infliggono danni hanno una probabilità del $h% di aumentare del $m1% la tua probabilità di blocco. Dura $20128d o $20128n blocchi." },
    [20138] = { en = "Increases the armor bonus of your Devotion Aura by $s1%, and increases all healing received by party members affected by your Auras by $m2%.", description = "Aumenta del $s1% il bonus all'armatura dell'Aura di Devozione e del $m2% tutte le cure ricevute dai membri del gruppo influenzati dalle tue Aure." },
    [20150] = { en = "Increases the amount of damage absorbed by your shield by $m1%, and gives your blocks a $m2% chance to restore $1310925m1% of your maximum Mana.  May only occur once every $proccooldown sec.", description = "Aumenta del $m1% i danni assorbiti dal tuo scudo e dà ai tuoi blocchi una probabilità del $m2% di ripristinare il $1310925m1% del tuo mana massimo. Può attivarsi solo una volta ogni $proccooldown sec." },
    [20162] = { en = "Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20188d, increasing Holy damage taken by up to $20188s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino dello spirito di un crociato, conferendogli $s1 potenza d'attacco in mischia. Il paladino attacca anche il $s2% più velocemente, ma infligge meno danni a ogni colpo. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20188d, aumentando fino a $20188s1 i danni sacri che subisce. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20163] = { en = "Fills the Paladin with divine fury for $d, causing melee attacks to deal an additional $20231s1 Holy damage. While a shield is equipped, each attack also grants an absorb shield equal to $m2% of the Holy damage dealt.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy causes $20183s1 Holy damage to an enemy and taunts the target to attack you for $20232d.", description = "Per $d, pervade il paladino di furia divina, facendo sì che gli attacchi in mischia infliggano $20231s1 danni sacri aggiuntivi. Quando è equipaggiato uno scudo, ogni attacco conferisce anche uno scudo d'assorbimento pari al $m2% dei danni sacri inflitti. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo infligge $20183s1 danni sacri a un nemico e lo provoca ad attaccarti per $20232d." },
    [20164] = { en = "Fills the Paladin with the spirit of justice for $d, giving each melee attack a chance to stun for $20170d.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20184d, preventing them from fleeing.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino dello spirito della giustizia, dando a ogni attacco in mischia una probabilità di stordire per $20170d. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20184d, impedendogli di fuggire. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20165] = { en = "Fills the Paladin with divine light for $d, giving each melee attack a chance to heal the Paladin for $20167s1.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20185d, granting melee attacks made against the judged enemy a chance of healing the attacker for $20267s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino di luce divina, dando a ogni attacco in mischia una probabilità di curarlo di $20167s1. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20185d; gli attacchi in mischia contro il nemico giudicato hanno una probabilità di curare l'attaccante di $20267s1. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20166] = { en = "Fills the Paladin with divine wisdom for $d, giving each melee attack a chance to restore $20168s1 of the Paladin's mana.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20186d, granting attacks and spells used against the judged enemy a chance to restore $20268s1 mana to the attacker.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino di saggezza divina, dando a ogni attacco in mischia una probabilità di ripristinare $20168s1 mana del paladino. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20186d; gli attacchi e gli incantesimi usati contro il nemico giudicato hanno una probabilità di ripristinare $20268s1 mana all'attaccante. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20177] = { en = "Gives you a $m1% chance to gain an extra attack after Blocking a melee attack and a ${$m1*2.5}% chance to gain an extra attack after being the victim of a non-periodic critical strike.", description = "Ti dà una probabilità del $m1% di sferrare un attacco aggiuntivo dopo aver bloccato un attacco in mischia e una probabilità del ${$m1*2.5}% di sferrare un attacco aggiuntivo dopo aver subito un colpo critico non periodico." },
    [20196] = { en = "Increases the damage you deal with one-handed melee weapons by $s1%.", description = "Aumenta del $s1% i danni inflitti con le armi da mischia a una mano." },
    [20205] = { en = "Gives your Flash of Light, Holy Light, and Light's Vigil spells a $s1% chance to not lose casting time when you take damage.", description = "Dà agli incantesimi Lampo di Luce, Luce Sacra e Vigilia della Luce una probabilità del $s1% di non perdere tempo di lancio quando subisci danni." },
    [20210] = { en = "After getting a critical effect from your Flash of Light, Holy Light, Light's Vigil, or Holy Shock heal spell you have a $m1% chance to gain Mana equal to $m3% of the base cost of the spell.", description = "Dopo aver ottenuto un effetto critico con gli incantesimi di cura Lampo di Luce, Luce Sacra, Vigilia della Luce o Scossa Sacra, hai una probabilità del $m1% di ottenere mana pari al $m3% del costo base dell'incantesimo." },
    [20216] = { en = "When activated, gives your next Flash of Light, Holy Light, or Holy Shock spell a $s1% critical effect chance.", description = "Quando si attiva, conferisce al prossimo incantesimo Lampo di Luce, Luce Sacra o Scossa Sacra una probabilità di effetto critico del $s1%." },
    [20218] = { en = "Increases Holy damage done by party members within $a1 yards by $s1%.  Players may only have one Aura on them per Paladin at any one time.", description = "Aumenta i danni sacri inflitti dai membri del gruppo entro $a1 metri del $s1%. Ogni paladino può applicare una sola Aura a ciascun giocatore." },
    [20224] = { en = "Increases the damage done by your Seals and Judgements by $s1%.", description = "Aumenta del $s1% i danni inflitti dai tuoi Sigilli e Giudizi." },
    [20237] = { en = "Increases the amount healed by your Holy Light, Flash of Light, and Holy Shock spells by $s1%.", description = "Aumenta del $s1% le cure dei tuoi incantesimi Luce Sacra, Lampo di Luce e Scossa Sacra." },
    [20254] = { en = "Increases the effect of your Concentration Aura by an additional $m1%, and your Concentration Aura also reduces the duration of Silence and Interrupt effects on your party members by $m2%.", description = "Aumenta di un ulteriore $m1% l'effetto della tua Aura di Concentrazione; inoltre, l'Aura riduce del $m2% la durata degli effetti di Silenzio e interruzione sui membri del gruppo." },
    [20257] = { en = "Increases your total Intellect by $s1%.", description = "Aumenta del $s1% il tuo Intelletto totale." },
    [20262] = { en = "Increases your Strength by $s1%.", description = "Aumenta la tua Forza del $s1%." },
    [20305] = { en = "Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20300d, increasing Holy damage taken by up to $20300s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino dello spirito di un crociato, conferendogli $s1 potenza d'attacco in mischia. Il paladino attacca anche il $s2% più velocemente, ma infligge meno danni a ogni colpo. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20300d, aumentando fino a $20300s1 i danni sacri che subisce. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20306] = { en = "Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20301d, increasing Holy damage taken by up to $20301s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino dello spirito di un crociato, conferendogli $s1 potenza d'attacco in mischia. Il paladino attacca anche il $s2% più velocemente, ma infligge meno danni a ogni colpo. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20301d, aumentando fino a $20301s1 i danni sacri che subisce. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20307] = { en = "Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20302d, increasing Holy damage taken by up to $20302s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino dello spirito di un crociato, conferendogli $s1 potenza d'attacco in mischia. Il paladino attacca anche il $s2% più velocemente, ma infligge meno danni a ogni colpo. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20302d, aumentando fino a $20302s1 i danni sacri che subisce. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20308] = { en = "Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20303d, increasing Holy damage taken by up to $20303s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino dello spirito di un crociato, conferendogli $s1 potenza d'attacco in mischia. Il paladino attacca anche il $s2% più velocemente, ma infligge meno danni a ogni colpo. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20303d, aumentando fino a $20303s1 i danni sacri che subisce. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20347] = { en = "Fills the Paladin with divine light for $d, giving each melee attack a chance to heal the Paladin for $20333s1.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20344d, granting melee attacks made against the judged enemy a chance of healing the attacker for $20341s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino di luce divina, dando a ogni attacco in mischia una probabilità di curarlo di $20333s1. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20344d; gli attacchi in mischia contro il nemico giudicato hanno una probabilità di curare l'attaccante di $20341s1. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20348] = { en = "Fills the Paladin with divine light for $d, giving each melee attack a chance to heal the Paladin for $20334s1.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20345d, granting melee attacks made against the judged enemy a chance of healing the attacker for $20342s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino di luce divina, dando a ogni attacco in mischia una probabilità di curarlo di $20334s1. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20345d; gli attacchi in mischia contro il nemico giudicato hanno una probabilità di curare l'attaccante di $20342s1. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20349] = { en = "Fills the Paladin with divine light for $d, giving each melee attack a chance to heal the Paladin for $20340s1.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20346d, granting melee attacks made against the judged enemy a chance of healing the attacker for $20343s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino di luce divina, dando a ogni attacco in mischia una probabilità di curarlo di $20340s1. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20346d; gli attacchi in mischia contro il nemico giudicato hanno una probabilità di curare l'attaccante di $20343s1. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20356] = { en = "Fills the Paladin with divine wisdom for $d, giving each melee attack a chance to restore $20350s1 of the Paladin's mana.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20354d, granting attacks and spells used against the judged enemy a chance to restore $20352s1 mana to the attacker.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino di saggezza divina, dando a ogni attacco in mischia una probabilità di ripristinare $20350s1 mana del paladino. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20354d; gli attacchi e gli incantesimi usati contro il nemico giudicato hanno una probabilità di ripristinare $20352s1 mana all'attaccante. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20357] = { en = "Fills the Paladin with divine wisdom for $d, giving each melee attack a chance to restore $20351s1 of the Paladin's mana.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $20355d, granting attacks and spells used against the judged enemy a chance to restore $20353s1 mana to the attacker.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino di saggezza divina, dando a ogni attacco in mischia una probabilità di ripristinare $20351s1 mana del paladino. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $20355d; gli attacchi e gli incantesimi usati contro il nemico giudicato hanno una probabilità di ripristinare $20353s1 mana all'attaccante. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [20419] = { en = "Fills the Paladin with divine fury for $d, causing melee attacks to deal an additional $20415s1 Holy damage. While a shield is equipped, each attack also grants an absorb shield equal to $m2% of the Holy damage dealt.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy causes $20411s1 Holy damage to an enemy and taunts the target to attack you for $20232d.", description = "Per $d, pervade il paladino di furia divina, facendo sì che gli attacchi in mischia infliggano $20415s1 danni sacri aggiuntivi. Quando è equipaggiato uno scudo, ogni attacco conferisce anche uno scudo d'assorbimento pari al $m2% dei danni sacri inflitti. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo infligge $20411s1 danni sacri a un nemico e lo provoca ad attaccarti per $20232d." },
    [20421] = { en = "Fills the Paladin with divine fury for $d, causing melee attacks to deal an additional $20416s1 Holy damage. While a shield is equipped, each attack also grants an absorb shield equal to $m2% of the Holy damage dealt.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy causes $20412s1 Holy damage to an enemy and taunts the target to attack you for $20232d.", description = "Per $d, pervade il paladino di furia divina, facendo sì che gli attacchi in mischia infliggano $20416s1 danni sacri aggiuntivi. Quando è equipaggiato uno scudo, ogni attacco conferisce anche uno scudo d'assorbimento pari al $m2% dei danni sacri inflitti. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo infligge $20412s1 danni sacri a un nemico e lo provoca ad attaccarti per $20232d." },
    [20422] = { en = "Fills the Paladin with divine fury for $d, causing melee attacks to deal an additional $20417s1 Holy damage. While a shield is equipped, each attack also grants an absorb shield equal to $m2% of the Holy damage dealt.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy causes $20413s1 Holy damage to an enemy and taunts the target to attack you for $20232d.", description = "Per $d, pervade il paladino di furia divina, facendo sì che gli attacchi in mischia infliggano $20417s1 danni sacri aggiuntivi. Quando è equipaggiato uno scudo, ogni attacco conferisce anche uno scudo d'assorbimento pari al $m2% dei danni sacri inflitti. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo infligge $20413s1 danni sacri a un nemico e lo provoca ad attaccarti per $20232d." },
    [20423] = { en = "Fills the Paladin with divine fury for $d, causing melee attacks to deal an additional $20418s1 Holy damage. While a shield is equipped, each attack also grants an absorb shield equal to $m2% of the Holy damage dealt.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy causes $20414s1 Holy damage to an enemy and taunts the target to attack you for $20232d.", description = "Per $d, pervade il paladino di furia divina, facendo sì che gli attacchi in mischia infliggano $20418s1 danni sacri aggiuntivi. Quando è equipaggiato uno scudo, ogni attacco conferisce anche uno scudo d'assorbimento pari al $m2% dei danni sacri inflitti. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo infligge $20414s1 danni sacri a un nemico e lo provoca ad attaccarti per $20232d." },
    [20468] = { en = "While Righteous Fury is active, all damage taken is reduced by $m1%.", description = "Finché Furia Virtuosa è attiva, tutti i danni subiti sono ridotti del $m1%." },
    [20473] = { en = "Blasts the target with Holy energy, causing $25912s1 Holy damage to an enemy, or $25914s1 healing to an ally.", description = "Colpisce il bersaglio con energia sacra, infliggendo $25912s1 danni sacri a un nemico oppure curando un alleato di $25914s1." },
    [20550] = { en = "Total Health increased by $s1% and chance to hit increased by $s2%.", description = "Salute totale aumentata del $s1% e probabilità di colpire aumentata del $s2%." },
    [20554] = { en = "Increases your spellcasting and attack speed by $s1% for $26635d.", description = "Aumenta del $s1% la velocità di lancio degli incantesimi e d'attacco per $26635d." },
    [20573] = { en = "Duration of Stun effects on you reduced by $s1%.", description = "Riduce del $s1% la durata degli effetti di stordimento su di te." },
    [20580] = { en = "Activate to slip into the shadows, reducing the chance for enemies to detect your presence. Lasts until cancelled or upon moving. Using this ability in combat discourages enemies from attacking you, but increases the cooldown to 2 min.", description = "Ti nascondi nell'ombra, riducendo la probabilità che i nemici ti individuino. Dura finché non viene annullato o finché non ti muovi. Usare questa abilità in combattimento scoraggia i nemici dall'attaccarti, ma aumenta il tempo di recupero a 2 min." },
    [20582] = { en = "Dodge chance increased by $s1% and movement speed increased by $s2%. Night Elf Rogues and Druids are harder to detect in Stealth as if they were 1 level higher.", description = "Probabilità di schivata aumentata del $s1% e velocità di movimento aumentata del $s2%. I ladri e i druidi Elfi della Notte sono più difficili da individuare in Furtività, come se fossero di 1 livello superiore." },
    [20585] = { en = "Transform into a wisp upon death, increasing movement speed by $20584s1%.", description = "Alla morte ti trasformi in un fuoco fatuo, aumentando la velocità di movimento del $20584s1%." },
    [20587] = { en = "Increases Stamina by $s3 and reduces physical damage taken by $s4 for $d. However, lowers Strength and Agility by $s1 and increases magical damage taken by up to $s5.", description = "Aumenta la Tempra di $s3 e riduce i danni fisici subiti di $s4 per $d. Tuttavia, riduce la Forza e l'Agilità di $s1 e aumenta fino a $s5 i danni magici subiti." },
    [20591] = { en = "Maximum Mana increased by $s1%.", description = "Mana massimo aumentato del $s1%." },
    [20594] = { en = "Instantly removes and grants immunity to all Bleed, Poison, and Disease effects, and reduces all Physical damage taken by $s1% for $d.", description = "Rimuove istantaneamente tutti gli effetti di Sanguinamento, Veleno e Malattia e ne conferisce l'immunità; inoltre riduce del $s1% tutti i danni fisici subiti per $d." },
    [20597] = { en = "Increases your critical strike chance with all spells and attacks by $s1% while you have a sword or two-handed sword equipped.", description = "Aumenta del $s1% la probabilità di critico con tutti gli incantesimi e gli attacchi quando hai equipaggiata una spada o una spada a due mani." },
    [20600] = { en = "Dramatically increases stealth detection for $d.", description = "Aumenta notevolmente l'individuazione della furtività per $d." },
    [20616] = { en = "Charge an enemy, causing $20614s2 damage and stunning it for $20614d.", description = "Carica un nemico, infliggendo $20614s2 danni e stordendolo per $20614d." },
    [20707] = { en = "Stores the friendly target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $3026s1 health and $3026q1 mana.", description = "Custodisce l'anima del bersaglio amico. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $3026s1 salute e $3026q1 mana." },
    [20733] = { en = "Curses an enemy, inflicting periodic Shadow damage over $d. If the target dies while afflicted by Black Arrow, $20734s1 $lSkeleton:Skeletons; will be summoned from the target's corpse.", description = "Maledice un nemico, infliggendo danni da ombra periodici per $d. Se il bersaglio muore mentre è affetto da Freccia Nera, dal suo cadavere vengono evocati $20734s1 $lSkeleton:Skeletons;." },
    [20752] = { en = "Creates a Lesser Soulstone.  The Soulstone can be used to store one target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $20758s1 health and $20758q1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra dell'Anima Inferiore. La Pietra dell'Anima può custodire l'anima di un bersaglio. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $20758s1 salute e $20758q1 mana.\r\n\r\nGli oggetti evocati scompaiono se si resta disconnessi per più di 15 minuti." },
    [20755] = { en = "Creates a Soulstone.  The Soulstone can be used to store one target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $20759s1 health and $20759q1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra dell'Anima. La Pietra dell'Anima può custodire l'anima di un bersaglio. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $20759s1 salute e $20759q1 mana.\r\n\r\nGli oggetti evocati scompaiono se si resta disconnessi per più di 15 minuti." },
    [20756] = { en = "Creates a Greater Soulstone.  The Soulstone can be used to store one target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $20760s1 health and $20760q1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra dell'Anima Superiore. La Pietra dell'Anima può custodire l'anima di un bersaglio. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $20760s1 salute e $20760q1 mana.\r\n\r\nGli oggetti evocati scompaiono se si resta disconnessi per più di 15 minuti." },
    [20757] = { en = "Creates a Major Soulstone.  The Soulstone can be used to store one target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $20761s1 health and $20761q1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra dell'Anima Maggiore. La Pietra dell'Anima può custodire l'anima di un bersaglio. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $20761s1 salute e $20761q1 mana.\r\n\r\nGli oggetti evocati scompaiono se si resta disconnessi per più di 15 minuti." },
    [20762] = { en = "Stores the friendly target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $20758s1 health and $20758q1 mana.", description = "Custodisce l'anima del bersaglio amico. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $20758s1 salute e $20758q1 mana." },
    [20763] = { en = "Stores the friendly target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $20759s1 health and $20759q1 mana.", description = "Custodisce l'anima del bersaglio amico. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $20759s1 salute e $20759q1 mana." },
    [20764] = { en = "Stores the friendly target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $20760s1 health and $20760q1 mana.", description = "Custodisce l'anima del bersaglio amico. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $20760s1 salute e $20760q1 mana." },
    [20765] = { en = "Stores the friendly target's soul.  If the target dies while their soul is stored, they will be able to resurrect with $20761s1 health and $20761q1 mana.", description = "Custodisce l'anima del bersaglio amico. Se il bersaglio muore mentre la sua anima è custodita, potrà risorgere con $20761s1 salute e $20761q1 mana." },
    [20798] = { en = "Increases the caster's armor by $s1 and speeds its health regeneration for $d.", description = "Aumenta l'armatura di $s1 e accelera la rigenerazione della salute per $d." },
    [20847] = { en = "When struck in combat has a ${$h/2}% chance of increasing all party member's armor by $18946s1 for $18946d. This chance is doubled in Strongholds and Cities.", description = "Quando vieni colpito in combattimento, hai una probabilità del ${$h/2}% di aumentare l'armatura di tutti i membri del gruppo di $18946s1 per $18946d. La probabilità raddoppia nelle roccaforti e nelle città." },
    [20922] = { en = "Consecrates the land beneath the Paladin, doing ${$1280347m1*8} Holy damage over $d to enemies who enter the area The first $s3 enemies who enter the area will take an additional ${$1280347m2*8} damage over $d.", description = "Consacra il terreno sotto il paladino, infliggendo ${$1280347m1*8} danni sacri in $d ai nemici che entrano nell'area. I primi $s3 nemici che vi entrano subiscono inoltre ${$1280347m2*8} danni aggiuntivi in $d." },
    [20923] = { en = "Consecrates the land beneath the Paladin, doing ${$1280348m1*8} Holy damage over $d to enemies who enter the area The first $s3 enemies who enter the area will take an additional ${$1280348m2*8} damage over $d.", description = "Consacra il terreno sotto il paladino, infliggendo ${$1280348m1*8} danni sacri in $d ai nemici che entrano nell'area. I primi $s3 nemici che vi entrano subiscono inoltre ${$1280348m2*8} danni aggiuntivi in $d." },
    [20924] = { en = "Consecrates the land beneath the Paladin, doing ${$1280349m1*8} Holy damage over $d to enemies who enter the area The first $s3 enemies who enter the area will take an additional ${$1280349m2*8} damage over $d.", description = "Consacra il terreno sotto il paladino, infliggendo ${$1280349m1*8} danni sacri in $d ai nemici che entrano nell'area. I primi $s3 nemici che vi entrano subiscono inoltre ${$1280349m2*8} danni aggiuntivi in $d." },
    [20925] = { en = "Increases chance to block by $s1% for $d, and deals $s2 Holy damage for each attack blocked while active.  Damage caused by Holy Shield causes 20% additional threat. Each block expends a charge. $n charges.", description = "Aumenta del $s1% la probabilità di blocco per $d e infligge $s2 danni sacri per ogni attacco bloccato durante l'effetto. I danni di Scudo Sacro generano il 20% di minaccia aggiuntiva. Ogni blocco consuma una carica. $n cariche." },
    [20929] = { en = "Blasts the target with Holy energy, causing $25911s1 Holy damage to an enemy, or $25913s1 healing to an ally.", description = "Colpisce il bersaglio con energia sacra, infliggendo $25911s1 danni sacri a un nemico oppure curando un alleato di $25913s1." },
    [20930] = { en = "Blasts the target with Holy energy, causing $25902s1 Holy damage to an enemy, or $25903s1 healing to an ally.", description = "Colpisce il bersaglio con energia sacra, infliggendo $25902s1 danni sacri a un nemico oppure curando un alleato di $25903s1." },
    [20988] = { en = "Increases your pet's Attack Power by $s1.", description = "Aumenta la potenza d'attacco del tuo famiglio di $s1." },
    [21008] = { en = "A mocking attack that causes $s1 damage and forces the target to focus attacks on you for $d.", description = "Attacco provocatorio che infligge $s1 danni e costringe il bersaglio a concentrarsi su di te per $d." },
    [21011] = { en = "Increases damage done to Demons by magical spells and effects by up to $s1.", description = "Aumenta fino a $s1 i danni inflitti ai Demoni dagli incantesimi e dagli effetti magici." },
    [21012] = { en = "Increases your damage dealt with off-hand attacks by $s1%.", description = "Aumenta del $s1% i danni inflitti dagli attacchi con la mano secondaria." },
    [21082] = { en = "Fills the Paladin with the spirit of a crusader for $d, granting $s1 melee attack power.  The Paladin also attacks $s2% faster, but deals less damage with each attack.  Only one Seal can be active on the Paladin at any one time.\r\n\r\nUnleashing this Seal's energy will judge an enemy for $21183d, increasing Holy damage taken by up to $21183s1.  Your melee strikes will refresh the spell's duration.  Only one Judgement per Paladin can be active at any one time.", description = "Per $d, pervade il paladino dello spirito di un crociato, conferendogli $s1 potenza d'attacco in mischia. Il paladino attacca anche il $s2% più velocemente, ma infligge meno danni a ogni colpo. Può essere attivo un solo Sigillo sul paladino alla volta.\r\n\r\nSprigionare l'energia di questo Sigillo giudica un nemico per $21183d, aumentando fino a $21183s1 i danni sacri che subisce. I tuoi attacchi in mischia rinnovano la durata dell'incantesimo. Ogni paladino può avere attivo un solo Giudizio alla volta." },
    [21098] = { en = "Blasts nearby enemies with ice, dealing $s1 damage, increasing the time between their attacks by $s2%, and movement speed by $s3%.", description = "Colpisce i nemici vicini con il ghiaccio, infliggendo $s1 danni, aumentando del $s2% l'intervallo tra i loro attacchi e riducendone la velocità di movimento del $s3%." },
    [21153] = { en = "Your attacks ignore $s1 of your enemies' armor for $d. This effect stacks up to 3 times.", description = "I tuoi attacchi ignorano $s1 armatura dei nemici per $d. L'effetto si accumula fino a 3 volte." },
    [21351] = { en = "Reduces the hit chance of Stun effects against you by $s1%.", description = "Riduce del $s1% la probabilità di essere colpito da effetti di stordimento." },
    [21403] = { en = "Shows the location of all nearby humanoids on the minimap for $d. Also substantially increases your stealth detection.", description = "Mostra sulla minimappa la posizione di tutti gli umanoidi vicini per $d. Aumenta inoltre notevolmente l'individuazione della furtività." },
    [21736] = { en = "Shows the location of all nearby humanoids in Winterax Hold for $d.", description = "Mostra per $d sulla minimappa la posizione di tutti gli umanoidi vicini a Rocca degli Invernoassi." },
    [21838] = { en = "Gives you a $h% chance to generate an additional Rage point whenever damage is dealt to you.", description = "Hai una probabilità del $h% di generare un punto Rabbia aggiuntivo ogni volta che subisci danni." },
    [21841] = { en = "You have a $h% chance whenever you deal melee damage to reduce your victim's Attack Power by $21840s1 for $21840d.", description = "Ogni volta che infliggi danni in mischia, hai una probabilità del $h% di ridurre la potenza d'attacco della vittima di $21840s1 per $21840d." },
    [21870] = { en = "Improves your chance to get a critical strike with Nature spells by $s1%.", description = "Aumenta dell'$s1% la probabilità di critico degli incantesimi di Natura." },
    [21920] = { en = "Increases spell frost damage by up to $s1 for $d.", description = "Aumenta fino a $s1 i danni degli incantesimi di Gelo per $d." },
    [21937] = { en = "+$s1 Attack Power against Giants.", description = "+$s1 potenza d'attacco contro i Giganti." },
    [21938] = { en = "Increases your pet's Attack Power by $20988s1.", description = "Aumenta la potenza d'attacco del tuo famiglio di $20988s1." },
    [21951] = { en = "Restores $s1 mana. Restore $s2 times as much if attacking an Earth Elementals, Golems, or Titan-forged enermy.\r\n", description = "Ripristina $s1 mana. Ne ripristina $s2 volte tanto se attacchi un elementale della Terra, un golem o un nemico forgiato dai Titani.\r\n" },
    [21956] = { en = "Absorbs $s1 Physical damage.  Lasts $d.", description = "Assorbe $s1 danni fisici. Dura $d." },
    [21958] = { en = "Reduces the hit chance of Stun and Fear effects against you by $s1%.", description = "Riduce del $s1% la probabilità di essere colpito da effetti di stordimento e Paura." },
    [21967] = { en = "Attack Power power increased by $s1.", description = "Potenza d'attacco aumentata di $s1." },
    [21969] = { en = "Has a $h% chance when struck in combat of increasing all stats by $21970s1 for $21970d1.", description = "Quando vieni colpito in combattimento, hai una probabilità del $h% di aumentare tutte le statistiche di $21970s1 per $21970d1." },
    [21978] = { en = "Chance on landing a damaging spell to deal $27860s1 Shadow damage and restore $27860s2 mana to you.", description = "Quando un incantesimo infligge danni, ha una probabilità di infliggere $27860s1 danni da ombra e ripristinarti $27860s2 mana." },
