    [22568] = { en = "Finishing move that causes damage per combo point and converts each extra point of energy into ${$m2/100}.1 additional damage.  Damage is increased by your Attack Power.\r\n   1 point  : 50-66 damage\r\n   2 points: 86-102 damage\r\n   3 points: 122-138 damage\r\n   4 points: 158-174 damage\r\n   5 points: 194-210 damage\r\n", description = "Mossa risolutiva che infligge danni in base ai punti combo e converte ogni punto energia aggiuntivo in ${$m2/100}.1 danni aggiuntivi. I danni aumentano in base alla tua potenza d'attacco.\r\n   1 punto  : 50-66 danni\r\n   2 punti: 86-102 danni\r\n   3 punti: 122-138 danni\r\n   4 punti: 158-174 danni\r\n   5 punti: 194-210 danni\r\n" },
    [22640] = { en = "Increases your Attack Speed by $s1% for $d1.", description = "Aumenta la tua velocità d'attacco del $s1% per $d1." },
    [22648] = { en = "$h% chance on a melee hit to call forth the spirit of Eskhandar to protect you in battle for $22649d.", description = "Probabilità del $h% con un colpo in mischia di evocare lo spirito di Eskhandar perché ti protegga in battaglia per $22649d." },
    [22685] = { en = "Increases Defense skill by $s1 for $d.", description = "Aumenta l'abilità Difesa di $s1 per $d." },
    [22725] = { en = "Permanently increase the defense value of an item worn on the chest, legs, hands or feet by $ec1. Only usable on items level $ecim and above.", description = "Aumenta permanentemente il valore di difesa di un oggetto indossato su torace, gambe, mani o piedi di $ec1. Utilizzabile solo su oggetti di livello $ecim o superiore." },
    [22731] = { en = "Restores $o1 health over $d.   Must remain seated while eating.   Also increases your Intellect by $18191s for $18191d.", description = "Ripristina $o1 salute in $d. Devi restare seduto mentre mangi. Inoltre, aumenta il tuo Intelletto di $18191s per $18191d." },
    [22748] = { en = "Increases healing done by spells and effects by up to $s1  and damage done by up to $s2.", description = "Aumenta fino a $s1 le cure inflitte dagli incantesimi e dagli effetti e fino a $s2 i danni inflitti." },
    [22755] = { en = "A razor edge improves your chance to get a critical strike by $s1%.", description = "Il filo affilato aumenta dell'$s1% la probabilità di infliggere un colpo critico." },
    [22767] = { en = "Reduces the hit chance of Root effects against you by $s1%.", description = "Riduce del $s1% la probabilità di essere colpito da effetti di intrappolamento." },
    [22790] = { en = "Increases Spirit by $s1, but decreases Intelligence by $s2 for $d.  Smoooooth.", description = "Aumenta lo Spirito di $s1 ma riduce l'Intelletto di $s2 per $d. Che stile." },
    [22812] = { en = "Your skin becomes as tough as bark. Physical damage taken is reduced by $s2%. While you are protected, damaging attacks will not cause spellcasting delays. Lasts $d.", description = "La tua pelle diventa dura come la corteccia. I danni fisici subiti sono ridotti del $s2%. Finché sei protetto, gli attacchi che infliggono danni non ritardano il lancio degli incantesimi. Dura $d." },
    [22820] = { en = "Chance for a critical hit with all spells and attacks increased by $s1%. Lasts $d. No effect while in a raid instance.\r\n", description = "Aumenta dell'$s1% la probabilità di colpo critico con tutti gli incantesimi e gli attacchi. Dura $d. Non ha effetto nelle istanze d'incursione.\r\n" },
    [22827] = { en = "Finishing move that causes damage per combo point and converts each extra point of energy into ${$m2/100}.1 additional damage.  Damage is increased by your Attack Power.\r\n   1 point  : 79-103 damage\r\n   2 points: 138-162 damage\r\n   3 points: 197-221 damage\r\n   4 points: 256-280 damage\r\n   5 points: 315-339 damage", description = "Mossa risolutiva che infligge danni in base ai punti combo e converte ogni punto energia aggiuntivo in ${$m2/100}.1 danni aggiuntivi. I danni aumentano in base alla tua potenza d'attacco.\r\n   1 punto  : 79-103 danni\r\n   2 punti: 138-162 danni\r\n   3 punti: 197-221 danni\r\n   4 punti: 256-280 danni\r\n   5 punti: 315-339 danni" },
    [22828] = { en = "Finishing move that causes damage per combo point and converts each extra point of energy into ${$m2/100}.1 additional damage.  Damage is increased by your Attack Power.\r\n   1 point  : 122-162 damage\r\n   2 points: 214-254 damage\r\n   3 points: 306-346 damage\r\n   4 points: 398-438 damage\r\n   5 points: 490-530 damage", description = "Mossa risolutiva che infligge danni in base ai punti combo e converte ogni punto energia aggiuntivo in ${$m2/100}.1 danni aggiuntivi. I danni aumentano in base alla tua potenza d'attacco.\r\n   1 punto  : 122-162 danni\r\n   2 punti: 214-254 danni\r\n   3 punti: 306-346 danni\r\n   4 punti: 398-438 danni\r\n   5 punti: 490-530 danni" },
    [22829] = { en = "Finishing move that causes damage per combo point and converts each extra point of energy into ${$m2/100}.1 additional damage.  Damage is increased by your Attack Power.\r\n   1 point  : 173-223 damage\r\n   2 points: 301-351 damage\r\n   3 points: 429-479 damage\r\n   4 points: 557-607 damage\r\n   5 points: 685-735 damage", description = "Mossa risolutiva che infligge danni in base ai punti combo e converte ogni punto energia aggiuntivo in ${$m2/100}.1 danni aggiuntivi. I danni aumentano in base alla tua potenza d'attacco.\r\n   1 punto  : 173-223 danni\r\n   2 punti: 301-351 danni\r\n   3 punti: 429-479 danni\r\n   4 punti: 557-607 danni\r\n   5 punti: 685-735 danni" },
    [22842] = { en = "Converts up to 10 Rage per second into health for $d.  Each point of Rage is converted into $s1% health.", description = "Per $d, converte fino a 10 punti Rabbia al secondo in salute. Ogni punto Rabbia viene convertito nel $s1% di salute." },
    [22850] = { en = "Grants the wielder $s1 Defense, $s2 Armor, $s3 Attack Power, and $s4 additional Attack Power against Dragonkin for $d.", description = "Conferisce a chi la impugna $s1 Difesa, $s2 Armatura, $s3 Potenza d'attacco e $s4 potenza d'attacco aggiuntiva contro i Draghi per $d." },
    [22888] = { en = "Increases critical chance of spells and attacks by $s1%, increases Attack Power by $s2, and increases spell damage and healing by up to $s4. Lasts $d. No effect while in a raid instance.", description = "Aumenta del $s1% la probabilità di critico di incantesimi e attacchi, di $s2 la potenza d'attacco e fino a $s4 i danni degli incantesimi e le cure. Dura $d. Non ha effetto nelle istanze d'incursione." },
    [22959] = { en = "Increases Fire damage taken from the Mage by $s1% per stack.", description = "Aumenta del $s1% per accumulo i danni da Fuoco subiti dal mago." },
    [23028] = { en = "Infuses the target's party and raid with brilliance, increasing their Intellect by $s1 for $d.", description = "Infondi nel gruppo e nell'incursione del bersaglio una brillantezza che aumenta il loro Intelletto di $s1 per $d." },
    [23060] = { en = "Attack Speed increased by $s1%.", description = "Velocità d'attacco aumentata del $s1%." },
    [23075] = { en = "Activates your Mithril Mechanical Dragonling to fight for you for $12749d.", description = "Attiva il tuo Draghetto Meccanico di Mithril, che combatterà al tuo fianco per $12749d." },
    [23097] = { en = "Reflects Fire spells back at their caster for $d.", description = "Riflette gli incantesimi di Fuoco verso il loro lanciatore per $d." },
    [23131] = { en = "Reflects Frost spells back at their caster for $d.", description = "Riflette gli incantesimi di Gelo verso il loro lanciatore per $d." },
    [23132] = { en = "Reflects Shadow spells back at their caster for $d.", description = "Riflette gli incantesimi d'Ombra verso il loro lanciatore per $d." },
    [23143] = { en = "Permanently enchant a Melee Weapon to add up to $22747s1 damage to spells.", description = "Incanta permanentemente un'arma da mischia per aggiungere fino a $22747s1 danni agli incantesimi." },
    [23144] = { en = "Permanently enchant a Melee Weapon to add up to $22748s1 points of healing to healing spells.", description = "Incanta permanentemente un'arma da mischia per aggiungere fino a $22748s1 punti di cura agli incantesimi di cura." },
    [23157] = { en = "Reduces the mana cost of your Arcane Shot by $s1.", description = "Riduce di $s1 il costo in mana di Tiro Arcano." },
    [23198] = { en = "Reduces all point-blank, area effect spell damage taken by $s1% when the caster is not facing the Rogue.", description = "Riduce di $s1% tutti i danni degli incantesimi ad area a distanza ravvicinata quando chi li lancia non è rivolto verso il ladro." },
    [23218] = { en = "Increases your movement speed by $s1% while in Bear, Cat, or Travel Form.  Only active outdoors.", description = "Aumenta del $s1% la velocità di movimento in Forma d'Orso, Felina o da Viaggio. Attivo solo all'aperto." },
    [23253] = { en = "Summon a third Terrordale Spirit 35% of the time.", description = "Hai una probabilità del 35% di evocare un terzo Spirito di Terrordale." },
    [23262] = { en = "Reduces the melee attack power of an enemy by $s1 for $d.", description = "Riduce di $s1 la potenza d'attacco in mischia di un nemico per $d." },
    [23300] = { en = "Increases the Holy damage bonus of your Judgement of the Crusader by $s1.", description = "Aumenta di $s1 il bonus ai danni sacri del tuo Giudizio del Crociato." },
    [23554] = { en = "Health or Mana gained from Drain Life and Drain Mana increased by $s1%.", description = "Aumenta del $s1% la salute o il mana ottenuti con Risucchio della Vita e Risucchio del Mana." },
    [23556] = { en = "Reduces the cooldown of your Tranquility and Hurricane spells by $s1%.", description = "Riduce del $s1% il tempo di recupero dei tuoi incantesimi Tranquillità e Uragano." },
    [23559] = { en = "Increases the Ranged Attack Power bonus of your Aspect of the Hawk by $s1%.", description = "Aumenta del $s1% il bonus alla potenza d'attacco a distanza del tuo Aspetto del Falco." },
    [23561] = { en = "Increases the threat generated by Sunder Armor by $s1%.", description = "Aumenta del $s1% la minaccia generata da Colpo dell'Armatura." },
    [23563] = { en = "Increases the attack power granted by Battle Shout by $s1.", description = "Aumenta di $s1 la potenza d'attacco conferita da Grido di Battaglia." },
    [23564] = { en = "Increases the chance of triggering a Judgement of Light heal by $s1%.", description = "Aumenta del $s1% la probabilità che si attivi una cura di Giudizio della Luce." },
    [23565] = { en = "Increases the radius of a Paladin's auras by $s1.", description = "Aumenta di $s1 il raggio delle Aure del paladino." },
    [23566] = { en = "Increases the damage of Multi-shot and Volley by $s1%.", description = "Aumenta del $s1% i danni di Tiro Multiplo e Raffica." },
    [23578] = { en = "You have a chance whenever you deal ranged damage to apply an Expose Weakness effect to the target. Expose Weakness increases the Ranged Attack Power of all attackers against that target by $23577s1 for $23577d.", description = "Quando infliggi danni a distanza, hai una probabilità di applicare al bersaglio l'effetto Debolezza Esposta. Debolezza Esposta aumenta di $23577s1 per $23577d la potenza d'attacco a distanza di tutti gli attaccanti contro quel bersaglio." },
    [23581] = { en = "Gives the Rogue a chance to inflict $23580s1 damage on the target and heal the Rogue for $23580s2 health every $23580t2 sec. for $23580d. on a melee hit.\r\n", description = "Con un colpo in mischia, il ladro ha una probabilità di infliggere $23580s1 danni al bersaglio e curarsi di $23580s2 salute ogni $23580t2 sec. per $23580d.\r\n" },
    [23584] = { en = "Increases your off-hand weapon damage by $m1%, off-hand Rage generation by $m2%, and chance to hit with off-hand attacks by $m3%.", description = "Aumenta del $m1% i danni dell'arma nella mano secondaria, del $m2% la generazione di Rabbia con essa e del $m3% la probabilità di colpire con gli attacchi della mano secondaria." },
    [23595] = { en = "Removes $s1 Bleed effect. While in or on Water, removes all Bleed, Disease, and Poison effects.", description = "Rimuove $s1 effetto di Sanguinamento. In acqua o sott'acqua rimuove tutti gli effetti di Sanguinamento, Malattia e Veleno." },
    [23602] = { en = "Generate ${$23602m1/10} Rage when you Dodge or Parry while you have a shield equipped.", description = "Genera ${$23602m1/10} Rabbia quando schivi o pari mentre hai uno scudo equipaggiato." },
    [23605] = { en = "Spell damage taken by target increased by $s1% for $d.", description = "Aumenta del $s1% i danni magici subiti dal bersaglio per $d." },
    [23674] = { en = "SO FAST!", description = "VELOCE!" },
    [23684] = { en = "2% chance on successful spellcast to increase your Spirit by $s1 for $d.", description = "Una probabilità del 2% a ogni lancio riuscito di un incantesimo di aumentare il tuo Spirito di $s1 per $d." },
    [23688] = { en = "2% chance on successful spellcast to increase your Spirit by $23684s1 for $23684d.", description = "Una probabilità del 2% a ogni lancio riuscito di un incantesimo di aumentare il tuo Spirito di $23684s1 per $23684d." },
    [23720] = { en = "Empowers your pet, increasing pet damage by $s1% and increasing pet armor by $s2% for $d. This spell will only affect an Imp, Succubus, Incubus, Voidwalker, or Felhunter.", description = "Potenzi il tuo famiglio, aumentandone i danni del $s1% e l'armatura del $s2% per $d. L'incantesimo ha effetto solo su un Imp, una Succube, un Incubus, un Vilguardiano o un Vilsegugio." },
    [23724] = { en = "Decreases the mana cost of all Druid shapeshifting forms by $s1% for $d.", description = "Riduce del $s1% il costo in mana di tutte le forme mutevoli del druido per $d." },
    [23734] = { en = "Aligns the Shaman with nature, increasing spell damage by $s1%, improving heal effects by $s2%, and increasing mana cost of spells by $s3% for $d.", description = "Sintonizza lo sciamano con la natura, aumentando del $s1% i danni degli incantesimi, del $s2% gli effetti di cura e del $s3% il costo in mana degli incantesimi per $d." },
    [23785] = { en = "Grants both the Warlock and the summoned demon an effect as long as that demon is active.\r\n\r\nImp - Increases Fire damage done by $m1%.\r\n\r\nVoidwalker - Reduces Physical damage taken by $m2%.\r\n\r\nSuccubus/Incubus - Increases Shadow damage done by $m3%.\r\n\r\nFelhunter - Reduces Magic damage taken by $m4%.", description = "Conferisce al warlock e al demone evocato un effetto finché il demone resta attivo.\r\n\r\nImp - Aumenta del $m1% i danni da Fuoco inflitti.\r\n\r\nVilguardiano - Riduce del $m2% i danni fisici subiti.\r\n\r\nSuccube/Incubus - Aumenta del $m3% i danni d'Ombra inflitti.\r\n\r\nVilsegugio - Riduce del $m4% i danni magici subiti." },
    [23921] = { en = "A passive ability that grants a $s1% chance to reflect spells while a shield is equipped.", description = "Abilità passiva che conferisce una probabilità del $s1% di riflettere gli incantesimi quando hai uno scudo equipaggiato." },
    [23930] = { en = "+$s1 Attack Power against Undead.  Allows the acquisition of Scourgestones on behalf of the Argent Dawn.", description = "+$s1 potenza d'attacco contro i Non Morti. Consente di raccogliere le Pietre del Flagello per conto dell'Alba d'Argento." },
    [24170] = { en = "Entangles the target with whipweed vines.", description = "Avvinghia il bersaglio con viticci di erbaccia frustante." },
    [24198] = { en = "Increases damage done to Undead by magical spells and effects by up to $s1.  Allows the acquisition of Scourgestones on behalf of the Argent Dawn.", description = "Aumenta fino a $s1 i danni inflitti ai Non Morti dagli incantesimi e dagli effetti magici. Consente di raccogliere le Pietre del Flagello per conto dell'Alba d'Argento." },
    [24238] = { en = "Finishing move that causes damage over time.  Damage increases per combo point:\r\n   1 point  : 228 damage over $d.\r\n   2 points: 354 damage over $d.\r\n   3 points: 480 damage over $d.\r\n   4 points: 606 damage over $d.\r\n   5 points: 732 damage over $d.", description = "Mossa risolutiva che infligge danni periodici. I danni aumentano in base ai punti combo:\r\n   1 punto  : 228 danni in $d.\r\n   2 punti: 354 danni in $d.\r\n   3 punti: 480 danni in $d.\r\n   4 punti: 606 danni in $d.\r\n   5 punti: 732 danni in $d." },
    [24248] = { en = "Finishing move that causes damage per combo point and converts each extra point of energy into $f1 additional damage:\r\n   1 point  : 170-220 damage\r\n   2 points: 295-345 damage\r\n   3 points: 420-470 damage\r\n   4 points: 545-595 damage\r\n   5 points: 670-720 damage", description = "Mossa risolutiva che infligge danni in base ai punti combo e converte ogni punto energia aggiuntivo in $f1 danni aggiuntivi:\r\n   1 punto  : 170-220 danni\r\n   2 punti: 295-345 danni\r\n   3 punti: 420-470 danni\r\n   4 punti: 545-595 danni\r\n   5 punti: 670-720 danni" },
    [24293] = { en = "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by $m1%.", description = "Quando rintracci Bestie, Demoni, Draghi, Elementali, Giganti, Umanoidi o Non Morti, aumenti del $m1% tutti i danni che infliggi al tipo di creatura rintracciato." },
    [24335] = { en = "A stinging shot that puts the target to sleep for $d.  Any damage will cancel the effect.  When the target wakes up, the Sting causes $24336o1 Nature damage over $24336d.", description = "Un colpo pungente che addormenta il bersaglio per $d. Qualsiasi danno interrompe l'effetto. Al risveglio, la puntura infligge $24336o1 danni da Natura in $24336d." },
    [24347] = { en = "Transform into a frenzy fish which grants water breathing and increases your swim speed by $s3%.\r\n\r\nCan only be used while swimming. Some combat actions may break this effect.", description = "Ti trasformi in un pesce frenetico, che ti permette di respirare sott'acqua e aumenta del $s3% la velocità di nuoto.\r\n\r\nUtilizzabile solo mentre nuoti. Alcune azioni di combattimento possono interrompere l'effetto." },
}
for id, record in pairs(verifiedSpellDescriptions) do
    if ns.data.spellDescriptionOverrides[id] == nil then
        ns.data.spellDescriptionOverrides[id] = record
    end
end
